#include "SampleFavorites.h"
static void testSampleFavorites(const File& root){
    auto catalog=root.getChildFile("sample-favorites-checks.json"),audio=root.getChildFile("favorite-source.wav"),other=root.getChildFile("favorite-other.flac");catalog.deleteFile();audio.replaceWithText("catalog fixture");other.replaceWithText("catalog fixture");StringArray files{"sentinel"};
    expect(loadSampleFavorites(catalog,files).wasOk()&&files.isEmpty(),"missing favorites catalog loads as an empty local library");auto initial=sampleFavoritesToken(catalog);expect(initial=="missing"&&editSampleFavorite(catalog,audio,true,initial).wasOk(),"available audio file can be favorited atomically");
    expect(loadSampleFavorites(catalog,files).wasOk()&&files.size()==1&&isSampleFavorite(files,audio),"sample favorite persists by absolute source path");auto token=sampleFavoritesToken(catalog),stored=catalog.loadFileAsString();expect(editSampleFavorite(catalog,audio,true,token).wasOk()&&sampleFavoritesToken(catalog)==token,"adding an existing favorite is idempotent without rewriting the catalog");
    expect(isSampleFavorite(files,File(audio.getFullPathName().toUpperCase())),"favorite membership follows case-insensitive Windows path identity");
    expect(editSampleFavorite(catalog,other,true,token).wasOk()&&editSampleFavorite(catalog,audio,false,token).failed(),"stale favorite choices reject instead of replacing a newer catalog");
    auto newest=catalog.loadFileAsString();expect(newest!=stored&&loadSampleFavorites(catalog,files).wasOk()&&files.size()==2,"stale mutation retains both current favorites");
    other.deleteFile();expect(loadSampleFavorites(catalog,files).wasOk()&&isSampleFavorite(files,other),"unavailable source files retain their favorite references");expect(editSampleFavorite(catalog,other,false).wasOk()&&loadSampleFavorites(catalog,files).wasOk()&&files.size()==1,"missing source favorite can be removed without opening or deleting audio");
    auto afterRemoval=catalog.loadFileAsString();expect(editSampleFavorite(catalog,other,true).failed()&&catalog.loadFileAsString()==afterRemoval,"unavailable audio cannot be added as a new favorite");auto keep=catalog.loadFileAsString();
    auto unsupported=root.getChildFile("favorite-source.txt");unsupported.replaceWithText("not an audio source");expect(editSampleFavorite(catalog,unsupported,true).failed()&&catalog.loadFileAsString()==keep,"unsupported file extension cannot partially change favorites");expect(editSampleFavorite(catalog,root,true).failed()&&catalog.loadFileAsString()==keep,"directories cannot be favorited as sample files");
    expect(saveSampleFavorites(catalog,{"relative.wav"}).failed()&&catalog.loadFileAsString()==keep,"relative paths reject before changing catalog");expect(saveSampleFavorites(catalog,{audio.getFullPathName(),audio.getFullPathName().toUpperCase()}).failed()&&catalog.loadFileAsString()==keep,"duplicate normalized paths reject atomically");
    StringArray maximum;for(int i=0;i<maxSampleFavorites;++i)maximum.add(root.getChildFile("fav-"+String(i)+".wav").getFullPathName());expect(saveSampleFavorites(catalog,maximum).wasOk()&&loadSampleFavorites(catalog,files).wasOk()&&files.size()==maxSampleFavorites,"all 256 favorite slots round-trip without requiring offline files to exist");keep=catalog.loadFileAsString();expect(editSampleFavorite(catalog,audio,true).failed()&&catalog.loadFileAsString()==keep,"favorite capacity rejects an additional file without losing existing references");maximum.add(audio.getFullPathName());expect(saveSampleFavorites(catalog,maximum).failed()&&catalog.loadFileAsString()==keep,"oversized direct favorite list fails atomically");
    for(auto text:{"{}","[]","{\"schema\":2,\"files\":[]}","{\"schema\":1,\"files\":7}","{\"schema\":1,\"files\":[7]}","{\"schema\":1,\"files\":[\"relative.wav\"]}","{\"schema\":1.5,\"files\":[]}"}){catalog.replaceWithText(text);files={audio.getFullPathName()};auto before=files;expect(loadSampleFavorites(catalog,files).failed()&&files==before,"malformed favorites read retains caller state");expect(editSampleFavorite(catalog,audio,true).failed()&&catalog.loadFileAsString()==text,"mutating a corrupt favorites catalog never overwrites it");}
    catalog.replaceWithText(String::repeatedString("x",maxSampleFavoritesBytes+1));files={audio.getFullPathName()};expect(loadSampleFavorites(catalog,files).failed()&&files.size()==1&&sampleFavoritesToken(catalog)=="oversized","oversized favorites input rejects without unbounded parsing");catalog.deleteFile();
    auto blocker=root.getChildFile("favorite-write-blocker");blocker.replaceWithText("blocks directory creation");expect(saveSampleFavorites(blocker.getChildFile("favorites.json"),{audio.getFullPathName()}).failed()&&blocker.loadFileAsString()=="blocks directory creation","directory creation failure preserves existing data");
    expect(sampleNameMatches("FM bell","Glass","Pulse FM Bell")&&sampleNameMatches("bell fm","Glass","Pulse FM Bell"),"Browser filter matches all words across name category and instrument independent of word order");expect(!sampleNameMatches("FM brass","Glass","Pulse FM Bell"),"all Browser query tokens must match");expect(sampleNameMatches("ÉCHO","Écho pad")&&sampleNameMatches("  \t ","Anything"),"Browser name filtering supports case-insensitive Unicode and empty queries");expect(sampleNameMatches("kick loops","kick.wav",root.getChildFile("Loops/kick.wav").getFullPathName()),"Browser filtering includes sample source folder paths");
}
